      "note": "Reine Fahrzeit: ca. 3 h 44.\n\nVom Holunderhof über die B100 durchs Drautal nach Spittal an der Drau und weiter über die A10/A2 bis in den Raum Velden. Dort Abfahrt und kurze Pause am Berger Parkplatz an der Augsdorfer Straße, dann über Gartenstraße und Augsdorfer Straße hinunter zur L96 Wörthersee-Süduferstraße. Dem Südufer über Auen, Dellach, Maria Wörth und Reifnitz folgen (Wegpunkt bei Wörthersee-Süduferstraße 115), anschließend über die L52/Rosentaler Straße zurück zur B83 und wieder auf die A2 Richtung Graz. Ausfahrt Graz-Webling, danach über B70, Grillweg, Am Jägergrund und Straßganger Straße zum Hotel Süd am Stemmerweg 10. Keine Schleife über Nockalmstraße oder Murau; Fokus auf zügiger, aber landschaftlich schöner Verbindung entlang des Wörthersees. Österreich-Vignette für A10/A2 erforderlich; aktuelle Verkehrslage und Baustelleninfos vor Abfahrt prüfen, insbesondere im Bereich der Tunnelkette Pack.",
