      "note": "Reine Fahrzeit: ca. 2 h 47.\n\nKüstenlinie über den Rand von Primošten und die Hauptstrasse nördlich der Altstadt von Trogir, dann auf der D8 über Dugi Rat und Omiš nach Makarska. Die Altstädte bei einem Stopp zu Fuss besuchen. Der zusätzliche Küstenanker verhindert die bisherige unbeabsichtigte A1-Abkürzung. Trogir–Split und Omiš möglichst ausserhalb der Spitzenzeit passieren; bei Stau zuerst Besichtigungen kürzen. Eine Autobahnalternative wäre eine bewusste Routenänderung und lässt Teile der Küste aus. Vor Abfahrt HAK für Wind, Baustellen und Sperren prüfen.\n\nOrientierungspunkt Makarska: INA Makarska-Ratac, Vukovarska 135 (43.306819, 17.007086). Ankunft und nächste Abfahrt verwenden diesen festen Punkt. Die Adresse von «Der Blick» wird erst nach Buchung bekannt; zur tatsächlich gewählten Unterkunft am jeweiligen Tag separat navigieren. Diese letzte Strecke ist nicht in Kilometer und Fahrzeit enthalten.",
