      "points": "Parcheggio P3, San Marino · 43.990701,12.514696 · 44.038832,12.551504 · Parcheggio Tiberio, Rimini · 44.211080,12.381783 · 44.417979,12.209275",
      "note": "Reine Fahrzeit: ca. 2 h 54.\n\nHügelstrecke nach San Marino und anschliessend über die Hauptstrasse Richtung Rimini. San Marino und Rimini bleiben flexible Besichtigungsstopps. Bei Regen oder schlechter Sicht die San-Marino-Schleife auslassen und die bewusste Direktalternative nach Ravenna wählen. Keine zusätzliche Berg- oder Passrunde. Die Fahrzeit gilt für die Hauptvariante über San Marino und Rimini. Bei Zeitverlust zuerst den zweiten Besuch verkürzen.\n\nP3 liegt an der Via Kennedy ausserhalb des engsten Altstadtkerns; Tiberio hat städtisch dokumentierte Motorradstellplätze. In ausgewiesenen Motorradflächen parken; P3-Schrankenregel für Motorräder vor dem Besuch bestätigen. Die Altstädte zu Fuss besuchen.\n\nDie Navigation besteht aus zwei Abschnitten. Nach dem Besuch am Parkplatz Tiberio in Rimini Abschnitt 2 öffnen. Strassenpunkte auf der Via Covignano, der SS16 und der Via Darsena halten den geplanten Verlauf fest; dort ist kein Halt vorgesehen.",
