      "currentAlternativeNotes": "Eigenes Ferienhaus im Olivenhain mit Küche, Waschmaschine und Privatparkplatz. Am 03.09. bei Booking für 18.–20.10. und zwei Erwachsene angezeigt: grosses 200-m²-Haus, CHF 539 insgesamt, kostenlos stornierbar vor 16.10. Steile Anfahrt laut Bewertung: nur wählen, wenn asphaltierte Zufahrt und Rangieren auch bei Nässe passen. Nicht mit dem allgemeinen Villa-Couple-Ab-Preis verwechseln.",
      "parking": "Beide nennen Privatparkplätze. Bei Petrarca steile Zufahrt laut Bewertung. Sichere Fläche für zwei Maschinen und asphaltierte Zufahrt schriftlich bestätigen lassen.",
